   102	func (d *decoder) wellformedInternal(depth int, checkBuiltinTags bool) (int, error) { //nolint:gocyclo
   103		t, _, val, indefiniteLength, err := d.wellformedHeadWithIndefiniteLengthFlag()
   104		if err != nil {
   105			return 0, err
   106		}
   107	
   108		switch t {
   109		case cborTypeByteString, cborTypeTextString:
   110			if indefiniteLength {
   111				if d.dm.indefLength == IndefLengthForbidden {
   112					return 0, &IndefiniteLengthError{t}
   113				}
   114				return d.wellformedIndefiniteString(t, depth, checkBuiltinTags)
   115			}
   116			valInt := int(val)
   117			if valInt < 0 {
   118				// Detect integer overflow
   119				return 0, errors.New("cbor: " + t.String() + " length " + strconv.FormatUint(val, 10) + " is too large, causing integer overflow")
   120			}
   121			if len(d.data)-d.off < valInt { // valInt+off may overflow integer
   122				return 0, io.ErrUnexpectedEOF
   123			}
   124			d.off += valInt
