   127			depth++
   128			if depth > d.dm.maxNestedLevels {
   129				return 0, &MaxNestedLevelError{d.dm.maxNestedLevels}
   130			}
   131	
   132			if indefiniteLength {
   133				if d.dm.indefLength == IndefLengthForbidden {
   134					return 0, &IndefiniteLengthError{t}
   135				}
   136				return d.wellformedIndefiniteArrayOrMap(t, depth, checkBuiltinTags)
   137			}
   138	
   139			valInt := int(val)
   140			if valInt < 0 {
   141				// Detect integer overflow
   142				return 0, errors.New("cbor: " + t.String() + " length " + strconv.FormatUint(val, 10) + " is too large, it would cause integer overflow")
   143			}
