   145			if t == cborTypeArray {
   146				if valInt > d.dm.maxArrayElements {
   147					return 0, &MaxArrayElementsError{d.dm.maxArrayElements}
   148				}
   149			} else {
   150				if valInt > d.dm.maxMapPairs {
   151					return 0, &MaxMapPairsError{d.dm.maxMapPairs}
   152				}
   153			}
   154	
   155			count := 1
   156			if t == cborTypeMap {
   157				count = 2
   158			}
   159			maxDepth := depth
   160			for j := 0; j < count; j++ {
   161				for i := 0; i < valInt; i++ {
   162					var dpt int
   163					if dpt, err = d.wellformedInternal(depth, checkBuiltinTags); err != nil {
   164						return 0, err
   165					}
   166					if dpt > maxDepth {
   167						maxDepth = dpt // Save max depth
   168					}
   169				}
   170			}
   171			depth = maxDepth
