		} else {
			fmt.Printf("✗ %s: Unexpected error: %v\n", name, err)
		}
	}
}

func main() {
	// Test truncated tags with different argument sizes

	// Tag with 1-byte argument (0xd8) - needs 2 bytes total
	testCase("truncated tag 1-byte arg (empty)", []byte{}, true)
	testCase("truncated tag 1-byte arg (only header)", []byte{0xd8}, true)
	testCase("valid tag 1-byte arg", []byte{0xd8, 0x05}, false)

	// Tag with 2-byte argument (0xd9) - needs 3 bytes total
	testCase("truncated tag 2-byte arg (empty)", []byte{}, true)
	testCase("truncated tag 2-byte arg (only header)", []byte{0xd9}, true)
	testCase("truncated tag 2-byte arg (header + 1 byte)", []byte{0xd9, 0x00}, true)
	testCase("valid tag 2-byte arg", []byte{0xd9, 0x00, 0x05}, false)

	// Tag with 4-byte argument (0xda) - needs 5 bytes total
	testCase("truncated tag 4-byte arg (empty)", []byte{}, true)
	testCase("truncated tag 4-byte arg (only header)", []byte{0xda}, true)
	testCase("truncated tag 4-byte arg (header + 1 byte)", []byte{0xda, 0x00}, true)
	testCase("truncated tag 4-byte arg (header + 2 bytes)", []byte{0xda, 0x00, 0x00}, true)
	testCase("truncated tag 4-byte arg (header + 3 bytes)", []byte{0xda, 0x00, 0x00, 0x00}, true)
	testCase("valid tag 4-byte arg", []byte{0xda, 0x00, 0x00, 0x00, 0x05}, false)

	// Tag with 8-byte argument (0xdb) - needs 9 bytes total
	testCase("truncated tag 8-byte arg (empty)", []byte{}, true)
	testCase("truncated tag 8-byte arg (only header)", []byte{0xdb}, true)
	testCase("truncated tag 8-byte arg (header + 4 bytes)", []byte{0xdb, 0x00, 0x00, 0x00, 0x00}, true)
	testCase("valid tag 8-byte arg", []byte{0xdb, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05}, false)

	// Valid tags with content
	testCase("tag with content", []byte{0xc0, 0x64}, false) // tag 0 with text "d"
	testCase("tag 1 with integer", []byte{0xc1, 0x05}, false) // tag 1 with int 5

	// Invalid type (not a tag)
	testCase("non-tag data", []byte{0x05}, true) // positive integer 5

	// Special cases
	testCase("null", []byte{0xf6}, false) // null should be no-op
	testCase("undefined", []byte{0xf7}, false) // undefined should be no-op
}
