func testCase(name string, data []byte, expectError bool, expectedTagNum uint64) {
	var v cbor.RawTag
	err := v.UnmarshalCBOR(data)

	if expectError {
		if err != nil {
			fmt.Printf("✓ %s: Got expected error: %v\n", name, err)
		} else {
			fmt.Printf("✗ %s: Expected error but got none\n", name)
		}
